// "New from template" (Phase 5): lane templates generated by scripts/make-templates.ts from the
// social-posts templates. Documents use brand tokens; asset refs point at files in brand-kits/.
import type { Document } from "@post-studio/schema";
import luxPost from "../../../brand-kits/templates/lux-post.json" with { type: "json" };
import luxSquare from "../../../brand-kits/templates/lux-square.json" with { type: "json" };
import kitesSquare from "../../../brand-kits/templates/kites-square.json" with { type: "json" };
import mosaicSquare from "../../../brand-kits/templates/mosaic-square.json" with { type: "json" };
import studioSquare from "../../../brand-kits/templates/studio-square.json" with { type: "json" };

export interface TemplateData {
  id: string;
  kit: string;
  name: string;
  description: string;
  /** 'sha256:…' → file under brand-kits/ (e.g. 'assets/4c1a….png'). */
  assets: Record<string, string>;
  doc: Document;
}

export interface TemplateInfo {
  id: string;
  kit: string;
  name: string;
  description: string;
  frames: Array<{ id: string; name: string; w: number; h: number }>;
}

const TEMPLATES = new Map<string, TemplateData>(([luxPost, luxSquare, mosaicSquare, kitesSquare, studioSquare] as unknown as TemplateData[]).map((t) => [t.id, t]));

export function listTemplates(): TemplateInfo[] {
  return [...TEMPLATES.values()].map((t) => ({ id: t.id, kit: t.kit, name: t.name, description: t.description, frames: t.doc.frames.map((f) => ({ id: f.id, name: f.name, w: f.w, h: f.h })) }));
}

/** A fresh copy of a template document, with a title and language. Undefined when unknown. */
export function templateDoc(id: string, opts: { title?: string; lang?: string } = {}): { doc: Document; assets: Record<string, string> } | undefined {
  const t = TEMPLATES.get(id);
  if (!t) return undefined;
  const doc = structuredClone(t.doc);
  if (opts.title) doc.title = opts.title.slice(0, 200);
  if (opts.lang) doc.lang = opts.lang;
  doc.meta = { ...(doc.meta ?? {}), template: { ...((doc.meta?.template as object) ?? {}), id } };
  return { doc, assets: { ...t.assets } };
}
